663: fn handleKqueueError(event: *const std.c.Kevent, comptime errnoToError: fn (net.E) anyerror) ?anyerror {
664:     const has_error = (event.flags & EV_ERROR) != 0;
665:     const has_eof = (event.flags & EV_EOF) != 0;
666:     if (!has_error and !has_eof) return null;
667: 
668:     if (has_error) {
669:         // event.data contains the errno when EV_ERROR is set
670:         if (event.data != 0) {
671:             return errnoToError(@enumFromInt(@as(i32, @intCast(event.data))));
672:         }
673:     }
674: 
675:     const sock_err = net.getSockError(@intCast(event.ident)) catch return error.Unexpected;
676:     if (sock_err == 0) return null; // No actual error, caller should retry operation
677:     return errnoToError(@enumFromInt(sock_err));
678: }
