102: /// Determine whether `handle` should use the direct I/O path for streaming:
103: /// pollable (non-seekable) fds return true. On POSIX, they are also switched to
104: /// non-blocking mode (required by the readiness poll path). Seekable fds (regular
105: /// files, block devices) return false.
106: pub fn probePollable(handle: fs.fd_t) bool {
107:     if (builtin.os.tag == .windows) {
108:         // On Windows, streaming (overlapped, zero-offset) I/O only works for
109:         // non-seekable handles (pipes/devices); no non-blocking mode to set.
110:         return @import("../../os/windows.zig").isPollable(handle);
111:     } else {
112:         const posix = @import("../../os/posix.zig");
113:         if (!posix.isPollable(handle)) return false;
114:         posix.setNonblocking(handle) catch return false;
115:         return true;
116:     }
117: }
