3321:     var read_file: Io.File = .{ .handle = fds[0], .flags = .{ .nonblocking = true } };
3322:     var write_file: Io.File = .{ .handle = fds[1], .flags = .{ .nonblocking = true } };
3323:     defer read_file.close(io);
