34: /// A raw-mode handle for the controlling TTY.
35: pub const Tty = struct {
36:     io: std.Io,
37:     file: std.Io.File,
38:     original: posix.termios,
39: 
40:     /// Open the controlling TTY and enter raw mode. `deinit` restores termios.
41:     pub fn open(io: std.Io) !Tty {
42:         var file = try openDevice(io);
43:         errdefer file.close(io);
44:         const original = try posix.tcgetattr(file.handle);
45:         try posix.tcsetattr(file.handle, .FLUSH, rawTermios(original));
46:         return .{ .io = io, .file = file, .original = original };
47:     }
48: 
49:     /// POSIX reads use zio cancellation.
50:     pub fn shutdownInput(_: *Tty) void {}
51: 
52:     /// Restore termios and close the TTY.
53:     pub fn deinit(self: *Tty) void {
54:         posix.tcsetattr(self.file.handle, .FLUSH, self.original) catch |err| {
55:             std.log.scoped(.term).err("restore terminal failed: {}", .{err});
56:         };
57:         self.file.close(self.io);
58:     }
59: 
60:     /// Read bytes. The reactor waits when no data exists.
61:     pub fn read(self: *Tty, buffer: []u8) !usize {
62:         return self.file.readStreaming(self.io, &.{buffer});
63:     }
64: 
65:     /// Build a buffered TTY writer. The caller owns the buffer.
66:     pub fn writerStreaming(self: *Tty, buffer: []u8) std.Io.File.Writer {
67:         return self.file.writerStreaming(self.io, buffer);
68:     }
