70:     /// Read the TTY size with `TIOCGWINSZ`.
71:     pub fn getWinsize(self: *const Tty) !Winsize {
72:         var ws: posix.winsize = .{ .row = 0, .col = 0, .xpixel = 0, .ypixel = 0 };
73:         const rc = posix.system.ioctl(self.file.handle, posix.T.IOCGWINSZ, @intFromPtr(&ws));
74:         if (posix.errno(rc) != .SUCCESS) return error.IoctlFailed;
75:         return .{ .rows = ws.row, .cols = ws.col, .x_pixel = ws.xpixel, .y_pixel = ws.ypixel };
