79: /// Open the terminal device.
80: fn openDevice(io: std.Io) !std.Io.File {
81:     // `/dev/tty` fails to register with kqueue, so darwin needs the real device name
82:     if (builtin.os.tag.isDarwin()) {
83:         var buf: [posix.PATH_MAX]u8 = undefined;
84:         if (devicePath(&buf)) |path| {
85:             if (std.Io.Dir.openFileAbsolute(io, path, .{ .mode = .read_write })) |file| {
86:                 return file;
87:             } else |_| {}
88:         }
89:     }
90:     return std.Io.Dir.openFileAbsolute(io, "/dev/tty", .{ .mode = .read_write });
91: }
92: 
93: /// Return the device path of the first standard stream that is a terminal.
94: fn devicePath(buf: *[posix.PATH_MAX]u8) ?[]const u8 {
95:     const streams = [_]posix.fd_t{ posix.STDIN_FILENO, posix.STDOUT_FILENO, posix.STDERR_FILENO };
96:     for (streams) |fd| {
97:         if (std.c.isatty(fd) == 0) continue;
98:         const rc = posix.system.fcntl(fd, posix.F.GETPATH, @intFromPtr(buf));
99:         if (posix.errno(rc) != .SUCCESS) continue;
100:         const path = std.mem.sliceTo(buf, 0);
101:         // A caller can redirect a standard stream from `/dev/tty`; that name is the one to avoid.
102:         if (!std.fs.path.isAbsolute(path) or std.mem.eql(u8, path, "/dev/tty")) continue;
103:         return path;
104:     }
105:     return null;
106: }
