108: /// Build raw-mode termios from the saved state. Clear echo, canonical, and transform flags.
109: fn rawTermios(state: posix.termios) posix.termios {
110:     var raw = state;
111:     raw.iflag.IGNBRK = false;
112:     raw.iflag.BRKINT = false;
113:     raw.iflag.PARMRK = false;
114:     raw.iflag.ISTRIP = false;
115:     raw.iflag.INLCR = false;
116:     raw.iflag.IGNCR = false;
117:     raw.iflag.ICRNL = false;
118:     raw.iflag.IXON = false;
119:     raw.oflag.OPOST = false;
120:     raw.lflag.ECHO = false;
121:     raw.lflag.ECHONL = false;
122:     raw.lflag.ICANON = false;
123:     raw.lflag.ISIG = false;
124:     raw.lflag.IEXTEN = false;
125:     raw.cflag.CSIZE = .CS8;
126:     raw.cflag.PARENB = false;
127:     raw.cc[@intFromEnum(posix.V.MIN)] = 1;
128:     raw.cc[@intFromEnum(posix.V.TIME)] = 0;
129:     return raw;
130: }
