118:     const command = switch (cli.parse(args[1..])) {
119:         .command => |command| command,
120:         .help => |scope| {
121:             try printUsage(init.io, scope);
122:             return 0;
123:         },
124:         .diagnostic => |diagnostic| {
125:             report(diagnostic);
126:             return 2;
127:         },
128:     };
129: 
130:     // One executor owns every task in this process. Both seams take its `std.Io`.
131:     const reactor = try zio.Runtime.init(init.gpa, .{ .executors = .exact(1) });
132:     defer reactor.deinit();
133:     const io = reactor.io();
134: 
135:     const tui = command == .tui;
