143:     const cwd_len = try std.Io.Dir.cwd().realPath(io, &cwd_buf);
144: 
145:     // Independent session trees can share this store; each tree has one engine owner.
146:     const application = app.App.open(init.gpa, io, init.environ_map) catch |err| {
147:         std.log.err("yuke: the app did not start: {t}", .{err});
148:         return 1;
149:     };
150:     defer application.close();
151: 
152:     // The auth commands need the engine and the store, but no JavaScript host and no terminal view.
153:     if (try authStatus(init.gpa, io, application, command)) |status| return status;
154: 
155:     var extensions: extensions_mod.Extensions = undefined;
156:     try extensions.init(init.gpa, io, application, .{
157:         .host = .{
158:             .cwd = cwd_buf[0..cwd_len],
