221: pub fn pipe(flags: PipeFlags) PipeError![2]fd_t {
222:     switch (system) {
223:         std.c => {
224:             // BSD/non-Linux: use pipe() + fcntl()
225:             var fds: [2]fd_t = undefined;
226: 
227:             switch (errno(system.pipe(&fds))) {
228:                 .SUCCESS => {},
229:                 .FAULT => unreachable,
230:                 .NFILE => return error.SystemFdQuotaExceeded,
231:                 .MFILE => return error.ProcessFdQuotaExceeded,
232:                 else => |err| return unexpectedError(err),
233:             }
234:             errdefer {
235:                 close(fds[0]);
236:                 close(fds[1]);
237:             }
238: 
239:             // Set flags using fcntl
240:             if (flags.nonblocking) {
241:                 try setNonblocking(fds[0]);
242:                 try setNonblocking(fds[1]);
243:             }
244:             if (flags.cloexec) {
245:                 try setCloexec(fds[0]);
246:                 try setCloexec(fds[1]);
247:             }
248: 
249:             return fds;
250:         },
251:         std.os.linux => {
252:             var fds: [2]fd_t = undefined;
253:             const pipe_flags: std.os.linux.O = .{
254:                 .NONBLOCK = flags.nonblocking,
255:                 .CLOEXEC = flags.cloexec,
256:             };
257: 
258:             switch (errno(system.pipe2(&fds, pipe_flags))) {
259:                 .SUCCESS => return fds,
260:                 .FAULT => unreachable,
261:                 .INVAL => unreachable, // Invalid flags - would be a bug
262:                 .NFILE => return error.SystemFdQuotaExceeded,
263:                 .MFILE => return error.ProcessFdQuotaExceeded,
264:                 else => |err| return unexpectedError(err),
265:             }
266:         },
267:         else => @compileError("unsupported OS"),
268:     }
