445: /// Read from `file` at its current position into `data`, advancing the
446: /// position. Returns `error.EndOfStream` on EOF (OS returned 0 bytes).
447: fn fileReadStreamingImpl(
448:     file: Io.File,
449:     data: []const []u8,
450:     timeout: time.Timeout,
451:     clock: time.Clock,
452: ) (Io.Operation.FileReadStreaming.Error || Io.Cancelable || common.Timeoutable)!usize {
453:     var iovecs: [max_iovecs_len]os_fs.iovec = undefined;
454:     var count: usize = 0;
455:     for (data) |buf| {
456:         if (count == iovecs.len) break;
457:         if (buf.len != 0) {
458:             iovecs[count] = os_net.iovecFromSlice(buf);
459:             count += 1;
460:         }
461:     }
462:     if (count == 0) return 0;
463: 
464:     var op = ev.FileReadStreaming.init(stdIoHandleToZio(file.handle), .{ .iovecs = iovecs[0..count] });
465:     op.pollable = flagsReadPollable(&file.flags);
466:     try timedWaitForIoClock(&op.c, timeout, clock);
467:     const n = op.getResult() catch |err| switch (err) {
468:         error.BrokenPipe, error.Unseekable => return error.Unexpected,
469:         else => |e| return e,
470:     };
471:     return if (n == 0) error.EndOfStream else n;
472: }
