60: /// Read the pollable-cache state from `File.Flags`.
61: ///
62: /// When hacks are enabled, the `nonblocking` bool byte is overloaded:
63: ///  - 0x01: known pollable (opened non-blocking)
64: ///  - 0xCC: known not pollable (cached from previous probe)
65: ///  - other: unknown (determine lazily)
66: fn flagsReadPollable(flags: *const Io.File.Flags) ?bool {
67:     if (zio_options.no_hacks) {
68:         return if (flags.nonblocking) true else null;
69:     }
70:     return switch (@as(*const u8, @ptrCast(flags)).*) {
71:         0x01 => true,
72:         0xCC => false,
73:         else => null,
74:     };
75: }
