77: /// Write the pollable verdict into `File.Flags`.
78: fn flagsWritePollable(flags: *Io.File.Flags, pollable: bool) void {
79:     if (zio_options.no_hacks) {
80:         flags.nonblocking = pollable;
81:         return;
82:     }
83:     @as(*u8, @ptrCast(flags)).* = if (pollable) 0x01 else 0xCC;
