422: /// The kernel removes a closed fd's *already-applied* knotes automatically, but a
423: /// socket EV_ADD still sitting un-flushed in change_buffer would be applied after
424: /// the fd is closed — and if the fd number is reused before the next poll, it
425: /// would arm the stale registration on the wrong socket on this loop. Drop any
426: /// pending changes for this fd so they cannot outlive it. (We deliberately do not
427: /// enqueue an EV_DELETE: a buffered delete flushes after the close and could hit a
428: /// reused fd, reintroducing the same hazard.) Called by sockreg.unregister.
429: pub fn unregisterCleanup(self: *Self, fd: NetHandle) void {
430:     const ident: usize = @intCast(fd);
431:     var i: usize = 0;
432:     while (i < self.change_buffer.items.len) {
433:         const ch = self.change_buffer.items[i];
434:         // Match only this loop's socket registrations (tagged with sock_marker),
435:         // not other changes that may share the ident — on Darwin the wall timers
436:         // use idents 0/1 and the async waker is EVFILT_USER, so an ident-only
437:         // match could drop a pending timer arm and wedge it.
438:         if (ch.ident == ident and ch.udata == sock_marker) {
439:             // orderedRemove preserves the relative order of the remaining changes,
440:             // which matters for any same-(ident,filter) ADD/DELETE pairing.
441:             _ = self.change_buffer.orderedRemove(i);
442:         } else {
443:             i += 1;
444:         }
445:     }
446: }
