2456:         const executors = 3;
2457:         const waves = 5;
2458:         const per_wave = 12;
2459:         const total = 8 * 1024;
2460:         const chunk = 2048;
2461:         const io_timeout = Timeout.fromMilliseconds(5_000);
2462: 
2463:         const Shared = struct {
2464:             conns: std.atomic.Value(u32) = .init(0),
2465:             verified: std.atomic.Value(u32) = .init(0),
2466:             errors: std.atomic.Value(u32) = .init(0),
2467:             done: std.atomic.Value(bool) = .init(false),
2468:         };
2469: 
2470:         fn pat(id: usize, i: usize) u8 {
2471:             return @truncate(id *% 31 +% i);
2472:         }
2473: 
2474:         fn nudge() void {}
2475: 
2476:         fn handler(stream: Stream, sh: *Shared) void {
2477:             defer stream.close();
2478:             var buf: [chunk]u8 = undefined;
2479:             while (true) {
2480:                 const n = stream.read(&buf, io_timeout) catch {
2481:                     _ = sh.errors.fetchAdd(1, .monotonic);
2482:                     return;
2483:                 };
2484:                 if (n == 0) return; // peer closed its send side
2485:                 stream.writeAll(buf[0..n], io_timeout) catch {
2486:                     _ = sh.errors.fetchAdd(1, .monotonic);
2487:                     return;
2488:                 };
