2504:                 _ = sh.errors.fetchAdd(1, .monotonic);
2505:                 port_ch.send(0) catch {};
2506:                 return;
2507:             };
2508:             defer srv.close();
2509:             port_ch.send(srv.socket.address.ip.getPort()) catch return;
2510: 
2511:             var handlers: Group = .init;
2512:             defer handlers.wait() catch {};
2513:             while (!sh.done.load(.acquire)) {
