/// Arm/update/disarm the given wall clock's timerfd to an absolute deadline (ns
/// in that clock's epoch; null = disarm). Returns false only if it couldn't arm
/// a pending deadline, so the loop folds that clock into the capped poll timeout.
pub fn syncWallTimer(self: *Self, clock: Clock, deadline: ?u64) bool {
    const idx: usize = switch (clock) {
        .boot => 0,
        .real => 1,
        else => unreachable,
        },
        .freebsd, .netbsd => {
            while (true) {
                const rc = c.eventfd_read(fd, &value);
                switch (posix.errno(rc)) {
                    .SUCCESS => return value,
                    .INTR => continue,
                    .AGAIN => return error.WouldBlock,
                    else => |err| std.debug.panic("eventfd_read: read failed: {}", .{err}),
                }
            }
        },
        else => @panic("Unsupported OS"),
    }
}

/// Write to the eventfd counter (8 bytes)
pub fn eventfd_write(fd: i32, value: u64) !void {
    const bytes = std.mem.asBytes(&value);
    switch (builtin.os.tag) {
        .linux => {
            while (true) {
                const rc = std.os.linux.write(fd, bytes.ptr, bytes.len);
                switch (posix.errno(rc)) {
                    .SUCCESS => {
                        std.debug.assert(rc == 8);
                        break;
                    },
                    .INTR => continue,
                    .AGAIN => return error.WouldBlock,
                    else => |err| std.debug.panic("eventfd_write: write failed: {}", .{err}),
                }
            }
        },
        .freebsd, .netbsd => {
            while (true) {
                const rc = c.eventfd_write(fd, value);
                switch (posix.errno(rc)) {
                    .SUCCESS => break,
                    .INTR => continue,
                    .AGAIN => return error.WouldBlock,
                    else => |err| std.debug.panic("eventfd_write: write failed: {}", .{err}),
                }
            }
        },
        else => @panic("Unsupported OS"),
    }
}

